window.CARDS=window.CARDS||{};CARDS["people-kiriyama-ikuto"]=[{"i":"sc-kiriyama-ikuto-y1v7_5-p89-1","v":"y1v7.5","y":1,"o":9,"k":"","w":"horikita-manabu nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  named in the brief name hit in horikita manabu s student council brief  passing mention   one is vice president kiriyama  from the second year class b  passing mention only  listed among members to keep an eye on  class b  with nagumo s circle  vice president under the president ayanokoji must oppose","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v7_5-p89-1\"><h3><span class=\"ttl\">Ch.4: named in the brief<\/span><span class=\"meta\">Y1V7.5 · p.89<\/span><\/h3><p class=\"setup\">Name-hit in Horikita Manabu’s student-council brief.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “One is Vice President Kiriyama, from the second-year Class B.”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Listed among members to keep an eye on; Class B, with Nagumo’s circle.<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Vice President under the president Ayanokōji must oppose.<span class=\"pg\">p.89<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p123-1\">→ After: Ch.5: with Nagumo outside the theater<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v7_5-p123-1","v":"y1v7.5","y":1,"o":9,"k":"","w":"nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 5  with nagumo outside the theater name hit in the entourage list when nagumo interrupts the double date  passing mention  student council members present with nagumo   secretaries mizowaki and tonokawa  and vice president kiriyama  entry records this name  passing mention only  entourage for the karaoke outing after the arm grab","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v7_5-p123-1\"><h3><span class=\"ttl\">Ch.5: with Nagumo outside the theater<\/span><span class=\"meta\">Y1V7.5 · p.123<\/span><\/h3><p class=\"setup\">Name-hit in the entourage list when Nagumo interrupts the double date.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: student council members present with Nagumo — Secretaries Mizowaki and Tonokawa, and Vice President Kiriyama (entry records this name).<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Entourage for the karaoke outing after the arm-grab.<span class=\"pg\">p.123<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p89-1\">← Before: Ch.4: named in the brief<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p154-1\">→ After: Ch.6: the vice president’s secret offer<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v7_5-p154-1","v":"y1v7.5","y":1,"o":9,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi horikita-manabu karuizawa-kei kiriyama-ikuto","q":"kiriyama ikuto ch 6  the vice president s secret offer lone student at the isolated campus meet  ayanokoji names him before he speaks  offers intel on nagumo in exchange for first year help   sorry to keep you waiting   i ve never agreed with nagumo once  i joined the student council because i admired horikita senpai  he was my senpai from class a  well  he used to be  i suppose   nagumo promised reform  kiriyama told her   he said capable students would be promoted to class a  no matter where they d started  there are a lot of dissatisfied people at this school who feel they were placed in the wrong class   if i left  what then  nagumo would be even more free to wreak havoc  i thought it best to infiltrate his inner circle and collect information try to find an opening i could exploit  if i hand that information to horikita senpai  i m sure he can do something with it   but you ll be seeing a lot more of the senior students from this point on  once the third semester begins  the school holds a special exam that brings all three grade levels together  i went through the same thing last year  first  and second  and occasionally even third years battle it out   every student who got on nagumo s bad side has been expelled  across the board   i won t make direct contact with you after this  i ll create a random e mail account and get in touch through that  recruits him for anti nagumo work  notes the relay made nagumo notice him  threatens mutual destruction if blown  opposed since the election  stayed vp to feed intel  first years are nagumo s next target after third years graduate  admired senpai from class a  the intended recipient of the intel  accepted as ayanokoji s partner without hesitation  infiltrated nagumo s inner circle while vice president  will not break school rules  expulsion risk  even for horikita s endorsement","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v7_5-p154-1\"><h3><span class=\"ttl\">Ch.6: the vice president’s secret offer<\/span><span class=\"meta\">Y1V7.5 · p.154–159<\/span><\/h3><p class=\"setup\">Lone student at the isolated campus meet; Ayanokōji names him before he speaks; offers intel on Nagumo in exchange for first-year help.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Sorry to keep you waiting.”<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\">“I’ve never agreed with Nagumo once. I joined the student council because I admired Horikita-senpai. He was my senpai from Class A. Well, he used to be, I suppose.”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\">“Nagumo promised reform,” Kiriyama told her. “He said capable students would be promoted to Class A, no matter where they’d started. There are a lot of dissatisfied people at this school who feel they were placed in the wrong…”<span class=\"pg\">p.155<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Nagumo promised reform,” Kiriyama told her. “He said capable students would be promoted to Class A, no matter where they’d started. There are a lot of dissatisfied people at this school who feel they were placed in the wrong class.”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I left, what then? Nagumo would be even more free to wreak havoc. I thought it best to infiltrate his inner circle and collect information…try to find an opening I could exploit. If I hand that information to Horikita-senpai, I’m sure he can do something with it.”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But you’ll be seeing a lot more of the senior students from this point on. Once the third semester begins, the school holds a special exam that brings all three grade levels together. I went through the same thing last year. First, and second, and occasionally even third years battle it out.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Every student who got on Nagumo’s bad side has been expelled. Across the board.”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I won’t make direct contact with you after this. I’ll create a random e-mail account and get in touch through that.”<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Recruits him for anti-Nagumo work; notes the relay made Nagumo notice him; threatens mutual destruction if blown.<span class=\"pg\">p.154–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Opposed since the election; stayed VP to feed intel; first-years are Nagumo’s next target after third-years graduate.<span class=\"pg\">p.155–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Admired senpai from Class A; the intended recipient of the intel.<span class=\"pg\">p.155–156, 159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Accepted as Ayanokōji’s partner without hesitation.<span class=\"pg\">p.154–155<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Infiltrated Nagumo’s inner circle while vice president; will not break school rules (expulsion risk) even for Horikita’s endorsement.<span class=\"pg\">p.155–158<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p123-1\">← Before: Ch.5: with Nagumo outside the theater<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p96-1","v":"y1v8","y":1,"o":10,"k":"","w":"nagumo-miyabi yukimura-teruhiko kiriyama-ikuto","q":"kiriyama ikuto ch 3  vice president at the card table accompanies nagumo into group six s room with tsunoda and ishikura for the breakfast duty old maid  passing mention   vice president kiriyama and two other third year students accompanied him  passing mention only  finishes second in the early rounds  next to nagumo in the late first year showdown  defeats yukimura in the second round while yukimura holds the joker  no line of his own attributed on these pages   presence through nagumo s party and the game order","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p96-1\"><h3><span class=\"ttl\">Ch.3: vice president at the card table<\/span><span class=\"meta\">Y1V8 · p.96–103<\/span><\/h3><p class=\"setup\">Accompanies Nagumo into group six’s room with Tsunoda and Ishikura for the breakfast-duty Old Maid.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “Vice President Kiriyama and two other third-year students accompanied him.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Finishes second in the early rounds; next to Nagumo in the late first-year showdown.<span class=\"pg\">p.100–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Defeats Yukimura in the second round while Yukimura holds the joker.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> No line of his own attributed on these pages — presence through Nagumo’s party and the game order.<span class=\"pg\">p.96–103<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p107-1\">→ After: Ch.3/4: passing mentions<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p107-1","v":"y1v8","y":1,"o":10,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto ch 3 4  passing mentions named as the next card player to finish after tsunoda  named as an alternative grouping option beside class d members and kei","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p107-1\"><h3><span class=\"ttl\">Ch.3/4: passing mentions<\/span><span class=\"meta\">Y1V8 · p.107, 120<\/span><\/h3><p class=\"setup\">Named as the next card-player to finish after Tsunoda.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Named as an alternative grouping option beside Class D members and Kei.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p96-1\">← Before: Ch.3: vice president at the card table<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p116-1\">→ After: Ch.4: the vice president’s coaching<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p116-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"kouenji-rokusuke ishizaki-daichi horikita-manabu nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  the vice president s coaching approaches the first year group in free time to correct attitude before lessons affect the large group s score   i think you should adjust your attitude a bit   you don t get to decide that  kouenji   you re too ignorant and infantile to even be called a high school student  lectures koenji on group unease  half the second years encircle when koenji answers back  names ishizaki first  then lumps  a number of you  as problems   koenji is the straw that breaks it  text notes he used to be class a  demoted after losing to nagumo  horikita s brother put them both in touch with ayanokoji  deep down wishes nagumo s downfall while still playing dutiful vice president for the large group s scores  frames evaluation as not only the final written test   instructors can take classroom behaviour into account  no further presence in chapter 4 after half 1","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p116-1\"><h3><span class=\"ttl\">Ch.4: the vice president’s coaching<\/span><span class=\"meta\">Y1V8 · p.116–119<\/span><\/h3><p class=\"setup\">Approaches the first-year group in free time to correct attitude before lessons affect the large group’s score.<\/p><p class=\"with\">with <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I think you should adjust your attitude a bit,”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\">“You don’t get to decide that, Kouenji.”<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\">“You’re too ignorant and infantile to even be called a high school student,”<span class=\"pg\">p.117<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Lectures Kōenji on group unease; half the second-years encircle when Kōenji answers back.<span class=\"pg\">p.116–117<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Names Ishizaki first, then lumps “a number of you” as problems — Kōenji is the straw that breaks it.<span class=\"pg\">p.116–118<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Text notes he used to be Class A, demoted after losing to Nagumo; Horikita’s brother put them both in touch with Ayanokōji.<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Deep down wishes Nagumo’s downfall while still playing dutiful vice president for the large group’s scores.<span class=\"pg\">p.116–117<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Frames evaluation as not only the final written test — instructors can take classroom behaviour into account.<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No further presence in chapter 4 after half 1.<span class=\"pg\">p.147<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p107-1\">← Before: Ch.3/4: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p173-1\">→ After: Ch.6 half 2: the blocked contact<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p173-1","v":"y1v8","y":1,"o":10,"k":"","w":"nagumo-miyabi ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto ch 6 half 2  the blocked contact named only in ayanokoji s contact plan  left a clue for him to find   kiriyama was in nagumo s group  even if he resented nagumo  he probably couldn t help me this time  in nagumo s group   the reason the contact fails  attempted second year channel before the asahina pivot  no presence beyond the plan line","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p173-1\"><h3><span class=\"ttl\">Ch.6 half 2: the blocked contact<\/span><span class=\"meta\">Y1V8 · p.173<\/span><\/h3><p class=\"setup\">Named only in Ayanokōji’s contact plan.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Left a clue for him to find; “Kiriyama was in Nagumo’s group. Even if he resented Nagumo, he probably couldn’t help me this time.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> In Nagumo’s group — the reason the contact fails.<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Attempted second-year channel before the Asahina pivot.<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> No presence beyond the plan line.<span class=\"pg\">p.173<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p116-1\">← Before: Ch.4: the vice president’s coaching<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v9-p100-1","v":"y1v9","y":1,"o":11,"k":"","w":"horikita-manabu kushida-kikyou kiriyama-ikuto","q":"kiriyama ikuto the source of manabu s report the vice president is who told manabu about kushida and nagumo  his information is what surfaces kushida s contact  ayanokoji flags that he cannot be completely trusted   manabu answers he does not know kiriyama as well as ayanokoji does  does not appear  named in the call only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v9-p100-1\"><h3><span class=\"ttl\">The source of Manabu’s report<\/span><span class=\"meta\">Y1V9 · p.100<\/span><\/h3><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> The vice president is who told Manabu about Kushida and Nagumo.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> His information is what surfaces Kushida’s contact.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Ayanokōji flags that he cannot be completely trusted — Manabu answers he does not know Kiriyama as well as Ayanokōji does.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Does not appear; named in the call only.<span class=\"pg\">p.100<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v9-p202-1\">→ After: The forum rumors<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v9-p202-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto the forum rumors meets ayanokoji at the school building after most students have gone home  ayanokoji reveals his plan to save ichinose  resists posting rumors on the forums  ayanokoji argues it would create a new relationship   i see  so you re telling me to post the rumors with my own phone  there d be no benefit in that for me at all  ayanokoji reveals kushida has already established contact with nagumo  kiriyama agrees to cooperate   why do you  horikita senpai s really placed a lot of trust in someone like you  hasn t he  recruits him to post the rumors on the school forums","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v9-p202-1\"><h3><span class=\"ttl\">The forum rumors<\/span><span class=\"meta\">Y1V9 · p.202–204<\/span><\/h3><p class=\"setup\">Meets Ayanokōji at the school building after most students have gone home; Ayanokōji reveals his plan to save Ichinose. Resists posting rumors on the forums; Ayanokōji argues it would create a new relationship. Ayanokōji reveals Kushida has already established contact with Nagumo; Kiriyama agrees to cooperate.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I see. So you’re telling me to post the rumors with my own phone? There’d be no benefit in that for me at all.”<span class=\"pg\">p.203<\/span><\/li><li class=\"q spoken\">“Why do you…… Horikita-senpai’s really placed a lot of trust in someone like you, hasn’t he?”<span class=\"pg\">p.204<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Recruits him to post the rumors on the school forums.<span class=\"pg\">p.202–204<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v9-p100-1\">← Before: The source of Manabu’s report<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v11_5-p94-1","v":"y1v11.5","y":1,"o":14,"k":"","w":"nagumo-miyabi asahina-nazuna horikita-manabu kiriyama-ikuto","q":"kiriyama ikuto ch 1  graduation farewells kiriyama appears with nagumo miyabi and other student council members during the third year farewells after the graduates  meeting  he is present in the circle around nagumo as nagumo discusses horikita manabu s graduation and the outcome of their conflict  accompanies him as a student council member during the farewells  present alongside her in the student council group  present during the farewell exchanges with the former president","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v11_5-p94-1\"><h3><span class=\"ttl\">Ch.1: Graduation farewells<\/span><span class=\"meta\">Y1V11.5 · p.94–104<\/span><\/h3><p class=\"setup\">Kiriyama appears with Nagumo Miyabi and other student council members during the third-year farewells after the graduates’ meeting. He is present in the circle around Nagumo as Nagumo discusses Horikita Manabu’s graduation and the outcome of their conflict.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"asahina-nazuna.html\">Asahina Nazuna<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Accompanies him as a student council member during the farewells.<span class=\"pg\">p.94–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Asahina Nazuna<\/b> Present alongside her in the student council group.<span class=\"pg\">p.94–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Present during the farewell exchanges with the former president.<span class=\"pg\">p.94–98<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kiriyama-ikuto-y2v2-p78-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto kiriyama attends the council meeting and is shaken he attends horikita s council meeting  nagumo probes why he came  and kiriyama nervously claims he was just interested in horikita s sister   i just was interested in horikita senpai s little sister  anything wrong with that  nervous and on edge   the battle with nagumo is already settled against him  nagumo probes him  he is shaken","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v2-p78-1\"><h3><span class=\"ttl\">Kiriyama attends the council meeting and is shaken<\/span><span class=\"meta\">Y2V2 · p.78–82<\/span><\/h3><p class=\"setup\">He attends Horikita&#x27;s council meeting; Nagumo probes why he came, and Kiriyama nervously claims he was just interested in Horikita&#x27;s sister.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I just was interested in Horikita-senpai&#x27;s little sister, anything wrong with that?&quot;<span class=\"pg\">p.82<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Nervous and on edge — the battle with Nagumo is already settled against him.<span class=\"pg\">p.78–82<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo probes him; he is shaken.<span class=\"pg\">p.82<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v2-p272-1\">→ After: Kiriyama warns Ayanokōji about Horikita<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v2-p272-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto kiriyama warns ayanokoji about horikita he meets ayanokoji and warns him not to interfere with nagumo  he reveals he wanted to battle nagumo personally but has given up  horikita appears and he warns about her involvement   i don t want you to get in my way  defeated and cautious   he advises ayanokoji to stay out of nagumo s way  he warns him about horikita and nagumo","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v2-p272-1\"><h3><span class=\"ttl\">Kiriyama warns Ayanokōji about Horikita<\/span><span class=\"meta\">Y2V2 · p.272–278<\/span><\/h3><p class=\"setup\">He meets Ayanokōji and warns him not to interfere with Nagumo; he reveals he wanted to battle Nagumo personally but has given up; Horikita appears and he warns about her involvement.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I don&#x27;t want you to get in my way.&quot;<span class=\"pg\">p.274<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Defeated and cautious — he advises Ayanokōji to stay out of Nagumo&#x27;s way.<span class=\"pg\">p.272–278<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He warns him about Horikita and Nagumo.<span class=\"pg\">p.272–278<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v2-p78-1\">← Before: Kiriyama attends the council meeting and is shaken<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v3-p120-1","v":"y2v3","y":2,"o":18,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama at the beach flags task he is present at the beach flags task  ayanokoji notes his presence and kiriyama warns him  he warns ayanokoji not to get in his way  he is mentioned in the context of nagumo s strategy  kiriyama is present in these scenes  see the year 2  vol  2 block for his full entry","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v3-p120-1\"><h3><span class=\"ttl\">Kiriyama at the Beach Flags Task<\/span><span class=\"meta\">Y2V3 · p.120–130<\/span><\/h3><p class=\"setup\">He is present at the Beach Flags Task; Ayanokōji notes his presence and Kiriyama warns him. He warns Ayanokōji not to get in his way. He is mentioned in the context of Nagumo&#x27;s strategy.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Kiriyama is present in these scenes; see the Year 2, Vol. 2 block for his full entry.<span class=\"pg\">p.120–130<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v3-p127-1\">→ After: Kiriyama warns Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v3-p127-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama warns ayanokoji he approaches ayanokoji at the beach flags task and warns him not to get in his way   i ll say it again just to be sure  don t get in my way  got it  hostile and on guard","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v3-p127-1\"><h3><span class=\"ttl\">Kiriyama warns Ayanokōji<\/span><span class=\"meta\">Y2V3 · p.127<\/span><\/h3><p class=\"setup\">He approaches Ayanokōji at the Beach Flags Task and warns him not to get in his way.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I&#x27;ll say it again just to be sure: Don&#x27;t get in my way, got it?&quot;<span class=\"pg\">p.127<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Hostile and on guard.<span class=\"pg\">p.127<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v3-p120-1\">← Before: Kiriyama at the Beach Flags Task<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p10-1","v":"y2v4","y":2,"o":19,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama mentioned in passing named in the context of the exam  passing mentions  not a distinct scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p10-1\"><h3><span class=\"ttl\">Kiriyama mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.10–284<\/span><\/h3><p class=\"setup\">Named in the context of the exam.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions; not a distinct scene presence.<span class=\"pg\">p.10–284<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.10–284<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4_5-p36-1","v":"y2v4.5","y":2,"o":20,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi horikita-manabu kiriyama-ikuto","q":"kiriyama ikuto kiriyama summons ayanokoji  the class a ticket and the expulsion of fifteen third years vice president kiriyama  message inviting him to the pool  is the most unlikely host imaginable  ayanokoji memorizes the results by the gym first  nagumo second  sakayanagi third  kiriyama s group fourth with 255 points   six short of the podium  all expulsions were third years  kiriyama waits by the pool  third years conspicuously absent from the quiet deck he chose  nagumo s allies are staring candidates  kiryuin teases them both before kiriyama abandons the poolside for a deck above   why did you want to bring me all the way out here   i won t beat around the bush  what did you do to nagumo on the last day of the uninhabited island exam  ayanokoji   give up  i don t know what you mean  my personal fight is still going on   now that nagumo s plan has changed  the others and i have started to see the adverse effects  i believe i told you before the uninhabited island exam  don t get in my way   it s true that i wanted to take down nagumo  if we couldn t beat him  it would be impossible for our class to rise back up to class a  however  that spirit gradually faded away by the time we reached the middle of our second year   we third years shifted to an individual competition early on  class points and school rules were of secondary importance  and we started playing according to the original rules proposed by nagumo   nagumo handed me a ticket to graduate from class a  so i decided to follow the rules that he made up that s what you wanted to hear  right   it was our mission to make sure that nagumo took first place  but your involvement disrupted the chain of command  leaving koenji to take first place while nagumo fell to second  the result was a significant loss in both class and private points   it costs 20 million points for a ticket to class a  so we re always looking for the best way to procure points  after this  you could say we re one ticket down   unable to do anything  those fifteen people were expelled  they didn t even have time to cry out   that guy has been playing around with the entire third year  the students without tickets are made to compete against each other  and then he ll make a show of giving the winning guy a ticket and make him pledge his allegiance   then what would you have me do  you won t tell me the details  but you won t see nagumo either  as it is  this is only going to get worse   that s fine  but you have to make a decision before nagumo makes his next move   i m going  if he knew we were meeting  things would become even more troublesome  his turn from nagumo s opponent to nagumo s ally is the structural fact of the third year  he predicts the stares will escalate and that nagumo will escalate beyond them  the 20 million point class a privilege is the core of nagumo s hold on his year  nagumo holds the class a tickets personally   held as verbal promises  not electronic transfers  individuals may hold up to 500 000 points  the rest being syphoned to nagumo  he pays off third years to clear the deck   quiet competence at arranging environments  once sworn to take him down  now one of his allies by coercion of 20 million points  he opposes the stares campaign even while following orders  summons him to extract the exam s last day secret  admits his own position  asks for a decision before nagumo s next move  ayanokoji invokes manabu s entrustment  kiriyama s face hardens at the name  fourth place with 255 points  six behind sakayanagi s third  the loss cost his group the top three bonus but also broke nagumo s chain of command  he accepts that his  backup  dispatch on short notice caused it","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4_5-p36-1\"><h3><span class=\"ttl\">Kiriyama summons Ayanokōji: the Class A ticket and the expulsion of fifteen third-years<\/span><span class=\"meta\">Y2V4.5 · p.36–53<\/span><\/h3><p class=\"setup\">Vice President Kiriyama, message inviting him to the pool, is the most unlikely host imaginable; Ayanokōji memorizes the results by the gym first: Nagumo second, Sakayanagi third, Kiriyama&#x27;s group fourth with 255 points — six short of the podium; all expulsions were third-years. Kiriyama waits by the pool; third-years conspicuously absent from the quiet deck he chose; Nagumo&#x27;s allies are staring candidates; Kiryūin teases them both before Kiriyama abandons the poolside for a deck above.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Why did you want to bring me all the way out here?”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\">“I won’t beat around the bush. What did you do to Nagumo on the last day of the uninhabited island exam, Ayanokōji?”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\">“Give up? I don&#x27;t know what you mean. My personal fight is still going on.”<span class=\"pg\">p.46<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Now that Nagumo&#x27;s plan has changed, the others and I have started to see the adverse effects. I believe I told you before the uninhabited island exam, don&#x27;t get in my way.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s true that I wanted to take down Nagumo. If we couldn&#x27;t beat him, it would be impossible for our class to rise back up to Class A. However, that spirit gradually faded away by the time we reached the middle of our second year.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We third-years shifted to an individual competition early on. Class points and school rules were of secondary importance, and we started playing according to the original rules proposed by Nagumo.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nagumo handed me a ticket to graduate from Class A, so I decided to follow the rules that he made up…That&#x27;s what you wanted to hear, right?”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was our mission to make sure that Nagumo took first place. But your involvement disrupted the chain of command, leaving Kōenji to take first place while Nagumo fell to second. The result was a significant loss in both class and private points.”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It costs 20 million points for a ticket to Class A, so we&#x27;re always looking for the best way to procure points. After this, you could say we&#x27;re one ticket down.”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unable to do anything, those fifteen people were expelled. They didn&#x27;t even have time to cry out.”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That guy has been playing around with the entire third year. The students without tickets are made to compete against each other, and then he&#x27;ll make a show of giving the winning guy a ticket and make him pledge his allegiance.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then what would you have me do? You won&#x27;t tell me the details, but you won&#x27;t see Nagumo either. As it is, this is only going to get worse.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…That&#x27;s fine. But you have to make a decision before Nagumo makes his next move.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m going. If he knew we were meeting, things would become even more troublesome.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> His turn from Nagumo&#x27;s opponent to Nagumo&#x27;s ally is the structural fact of the third-year; he predicts the stares will escalate and that Nagumo will escalate beyond them; the 20-million-point Class A privilege is the core of Nagumo&#x27;s hold on his year.<span class=\"pg\">p.46–53<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Nagumo holds the Class A tickets personally — held as verbal promises, not electronic transfers; individuals may hold up to 500,000 points, the rest being syphoned to Nagumo.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> He pays off third-years to clear the deck — quiet competence at arranging environments.<span class=\"pg\">p.44–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Once sworn to take him down; now one of his allies by coercion of 20 million points; he opposes the stares campaign even while following orders.<span class=\"pg\">p.46–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Summons him to extract the exam&#x27;s last-day secret; admits his own position; asks for a decision before Nagumo&#x27;s next move.<span class=\"pg\">p.45–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Ayanokōji invokes Manabu&#x27;s entrustment; Kiriyama&#x27;s face hardens at the name.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Fourth place with 255 points, six behind Sakayanagi&#x27;s third; the loss cost his group the top-three bonus but also broke Nagumo&#x27;s chain of command; he accepts that his &quot;backup&quot; dispatch on short notice caused it.<span class=\"pg\">p.37<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4_5-p153-1\">→ After: Mentions: Nagumo&#x27;s safety net<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4_5-p153-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto mentions  nagumo s safety net  fully understood that kiriyama had joined nagumo s side  as nagumo approached us  he stood next to ichinose   kiriyama had seen me and kei together  however  i didn t give any definite indication that we were dating","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4_5-p153-1\"><h3><span class=\"ttl\">Mentions: Nagumo&#x27;s safety net<\/span><span class=\"meta\">Y2V4.5 · p.153–154<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> &quot;fully understood that Kiriyama had joined Nagumo&#x27;s side. As Nagumo approached us, he stood next to Ichinose.&quot;<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Kiriyama had seen me and Kei together. However, I didn&#x27;t give any definite indication that we were dating.&quot;<span class=\"pg\">p.154<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4_5-p36-1\">← Before: Kiriyama summons Ayanokōji: the Class A ticket and the expulsion of fifteen third-years<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v7-p7-1","v":"y2v7","y":2,"o":23,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama ikuto mentioned in passing named in this volume  passing mentions on pages  p 78 79  passing mention only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v7-p7-1\"><h3><span class=\"ttl\">kiriyama-ikuto mentioned in passing<\/span><span class=\"meta\">Y2V7 · p.7-207<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.78-79.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.7<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kiriyama-ikuto-y2v9-p26-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"nagumo-miyabi ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto kiriyama  the 20 million point bet and his last stand as nagumo and ayanokoji finalize the bet on the student council election  kiriyama makes a final attempt to stop a game staking 20 million points and ayanokoji s expulsion   i ll get you the contract  it s one of two things  expulsion or 20 million   you don t have to risk your expulsion to play along with nagumo s game  he tries to warn horikita that ayanokoji has been drawn into something  but nagumo talks over him  and he is left holding his forehead   wait a minute  president  ayanokouji kun is here because  the pragmatic vice president   deeply uneasy about the stakes and the hidden bet  unable to rein in nagumo  and worried about ayanokoji being drawn in  his president  he cannot stop his impulsive high stakes game  tries to warn him off the gamble  notes he no longer hides his true nature","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v9-p26-1\"><h3><span class=\"ttl\">Kiriyama: the 20-million-point bet and his last stand<\/span><span class=\"meta\">Y2V9 · p.26–28<\/span><\/h3><p class=\"setup\">As Nagumo and Ayanokōji finalize the bet on the student-council election, Kiriyama makes a final attempt to stop a game staking 20 million points and Ayanokōji&#x27;s expulsion. He tries to warn Horikita that Ayanokōji has been drawn into something, but Nagumo talks over him, and he is left holding his forehead.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I&#x27;ll get you the contract. It&#x27;s one of two things: expulsion or 20 million.&quot;<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\">&quot;You don&#x27;t have to risk your expulsion to play along with Nagumo&#x27;s game.&quot;<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\">&quot;Wait a minute, President. Ayanokouji-kun is here because...&quot;<span class=\"pg\">p.28<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The pragmatic vice president — deeply uneasy about the stakes and the hidden bet, unable to rein in Nagumo, and worried about Ayanokōji being drawn in.<span class=\"pg\">p.26–28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> His president; he cannot stop his impulsive high-stakes game.<span class=\"pg\">p.26–28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tries to warn him off the gamble; notes he no longer hides his true nature.<span class=\"pg\">p.26<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v9-p75-1\">→ After: Kiriyama: inauguration, then exposed as the shoplifting mastermind<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v9-p75-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"horikita-suzune kiryuin-fuuka nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto kiriyama  inauguration  then exposed as the shoplifting mastermind at the handover he reminds ayanokoji their battle is not over   see you  ayanokouji  our battle isn t over yet  he arranges the student council hearing at nagumo s request and acts as the  familiar third party  but horikita s reasoning   that yamanaka and tachibana feared someone more than nagumo   lands on him   i understand that kiryuuin s upset that she was almost made to look like a shoplifter   there s no guarantee that the information ayanokouji has given you is true  as witnesses are about to be called  he confesses  he used nagumo s message assigning him a point earning job as cover and had yamanaka frame kiryuin   got it  let s stop this now   it means that there s no need to call witnesses  i admit that it was me who   i m sorry kiryuuin  but it had to be you  in order to achieve my goal  calculating and proud   a guaranteed class a ticket meant he would never move against nagumo  so he chose kiryuin as the target  cornered by solid logic  he owns the plot rather than drag witnesses into it  her first case as president sees through him  he confesses  he admits he framed her deliberately  cites his class a ticket as proof he had no motive  used his message as cover","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v9-p75-1\"><h3><span class=\"ttl\">Kiriyama: inauguration, then exposed as the shoplifting mastermind<\/span><span class=\"meta\">Y2V9 · p.75, 183–190<\/span><\/h3><p class=\"setup\">At the handover he reminds Ayanokōji their battle is not over. He arranges the student-council hearing at Nagumo&#x27;s request and acts as the &quot;familiar third party,&quot; but Horikita&#x27;s reasoning — that Yamanaka and Tachibana feared someone more than Nagumo — lands on him. As witnesses are about to be called, he confesses: he used Nagumo&#x27;s message assigning him a point-earning job as cover and had Yamanaka frame Kiryūin.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kiryuin-fuuka.html\">Kiryuin Fuuka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;See you, Ayanokouji. Our battle isn&#x27;t over yet.&quot;<span class=\"pg\">p.75<\/span><\/li><li class=\"q spoken\">&quot;I understand that Kiryuuin&#x27;s upset that she was almost made to look like a shoplifter.&quot;<span class=\"pg\">p.185<\/span><\/li><li class=\"q spoken\">&quot;There&#x27;s no guarantee that the information Ayanokouji has given you is true.&quot;<span class=\"pg\">p.188<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Got it. Let&#x27;s stop this now.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It means that there&#x27;s no need to call witnesses. I admit that it was me who...&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m sorry Kiryuuin, but it had to be you, in order to achieve my goal.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calculating and proud — a guaranteed Class A ticket meant he would never move against Nagumo, so he chose Kiryūin as the target; cornered by solid logic, he owns the plot rather than drag witnesses into it.<span class=\"pg\">p.183–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her first case as president sees through him; he confesses.<span class=\"pg\">p.188–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> He admits he framed her deliberately.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Cites his Class A ticket as proof he had no motive; used his message as cover.<span class=\"pg\">p.188–190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v9-p26-1\">← Before: Kiriyama: the 20-million-point bet and his last stand<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v9_5-p120-1","v":"y2v9.5","y":2,"o":26,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama mentioned in passing named in this volume  passing mention  locator pages  p 120  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v9_5-p120-1\"><h3><span class=\"ttl\">Kiriyama mentioned in passing<\/span><span class=\"meta\">Y2V9.5 · p.120<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.120; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kiriyama-ikuto-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama ikuto mentioned in passing named in this volume  passing mention  locator pages  p 169  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v12-p12-1\"><h3><span class=\"ttl\">kiriyama-ikuto mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.169; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"}];
